insert into public.bpt_posts(kind,slug,title,category,excerpt,content,author,status,published_at,created_at,updated_at) values('news','building-performance-technologies-expands-the-bpms-ecosystem','Building Performance Technologies expands the BPMS ecosystem','Company Update','The company is developing a connected system that brings together cloud software, mobile field capture, thermal documentation, LiDAR scanning, and building performance analysis.','The company is developing a connected system that brings together cloud software, mobile field capture, thermal documentation, LiDAR scanning, and building performance analysis. This comprehensive ecosystem enables building professionals to conduct thorough energy audits and performance assessments.','BPT Editorial Team','published','2026-06-25T10:00:00.000Z','2026-06-25T10:00:00.000Z','2026-06-25T10:00:00.000Z') on conflict(slug) do nothing;
insert into public.bpt_posts(kind,slug,title,category,excerpt,content,author,status,published_at,created_at,updated_at) values('news','bpmsfield-supports-mobile-first-building-documentation','BPMSField supports mobile-first building documentation','Product News','BPMSField is positioned as the mobile field companion for collecting photos, thermal images, LiDAR scans, and audit evidence directly from the jobsite.','BPMSField is positioned as the mobile field companion for collecting photos, thermal images, LiDAR scans, and audit evidence directly from the jobsite. The mobile app integrates seamlessly with the BPMS cloud platform for unified workflows.','BPT Editorial Team','published','2026-06-24T10:00:00.000Z','2026-06-24T10:00:00.000Z','2026-06-24T10:00:00.000Z') on conflict(slug) do nothing;
insert into public.bpt_posts(kind,slug,title,category,excerpt,content,author,status,published_at,created_at,updated_at) values('news','bpms-fluxsense-analyzer-concept-targets-direct-heat-flux-measurement','BPMS FluxSense Analyzer concept targets direct heat flux measurement','Innovation','The analyzer concept is designed to strengthen building diagnostics by measuring thermal transfer and supporting cloud-based performance modeling.','The analyzer concept is designed to strengthen building diagnostics by measuring thermal transfer and supporting cloud-based performance modeling. This hardware innovation will enhance the diagnostic capabilities of the BPMS ecosystem.','BPT Editorial Team','published','2026-06-23T10:00:00.000Z','2026-06-23T10:00:00.000Z','2026-06-23T10:00:00.000Z') on conflict(slug) do nothing;
